function compute(value) {

    var gearBoxGearRatio = 1000.

    var spindlePitch = 5.
    var timingBeltTransmissionGearRatio = 2.
    var motorIncrementPositions = 8388608
    var cylinderDiameter = 15.
    var cylinderVolume = 10000.

    var cylinderArea = cylinderDiameter ** 2. * Math.PI / 4.;

    var transmission = spindlePitch / (timingBeltTransmissionGearRatio * gearBoxGearRatio);
    var injectionRateRotation = transmission * cylinderArea;
    var injectionRateIncrement = injectionRateRotation / motorIncrementPositions;

    var pv = gearBoxGearRatio / cylinderArea;
    var iv = 1. / (injectionRateIncrement * 60.);
    var rv = 1. / (injectionRateIncrement * motorIncrementPositions);

    var velocity = value;
    var position = velocity * pv;
    var increment = Math.trunc(velocity * iv);
    var rotation = velocity * rv;

    return { velocity: velocity, position: position, increment: increment, rotation: rotation};
}


