function Scale(value, scale) {
        return (value - scale.min) / (scale.max - scale.min);
}

function Compute(PV, paramm) {

        SP = Scale(param.SP, param.scale);
        PV = Scale(PV, param.scale);

        var err = -(SP - PV);
        var dt = 1.0;

        var P = param.K.Kp * err;
        var I = param.K.Ki * err * dt + param['I'];

        var D = dt != 0. ? param.K.Kd * (err - param.err) / dt : 0.0;

        var MV = P + I + D;    
        MV = Math.min(Math.max(param.limit.min, MV), param.limit.max)

        param['I'] = I != NaN ? I : 0.0;        
        param.err = err;

        return { value: MV, param: param, control: { P: P, I:I, D:D }};
}

